// ─────────────────────────────────────────────────────────────────────────────
// Перевод вопросов к тексту
//
// ЗАЧЕМ. Вопрос к тексту задан на изучаемом языке — и это правильно: вопрос на
// русском превращает чтение в перевод. Но пословная подсказка отвечает «что
// значит это слово», а не «что у меня спрашивают»: в корейском вопросе смысл
// держится на окончании и на порядке слов, и ученик, разобравший все слова по
// одному, всё равно может не понять вопрос. Не поняв вопрос, он отвечает
// наугад — и текст, который он на самом деле прочитал, засчитывается как
// непонятый. Поэтому у каждого вопроса своя кнопка перевода, а не общий
// перевод после проверки.
//
// ПОЧЕМУ КЛЮЧ — СТРОКА, А НЕ id ВОПРОСА. Вопросы лежат в шести файлах данных
// (сцены четырёх языков, библиотека текстов, аудирование) и не имеют
// собственных идентификаторов: вопрос опознаётся местом в массиве. Ключ по
// месту ломается от любой вставки вопроса в середину и тихо подставляет чужой
// перевод. Ключ по самой строке от перестановок не зависит, а если формулировку
// перепишут — перевод просто исчезнет вместе с кнопкой (см. questionRu ниже:
// половинчатый перевод не показывается), и это заметно, в отличие от неверного.
//
// Ключи сверяются скриптом: `node scripts/checkQuestionRu.mjs` печатает вопросы
// без перевода.
// ─────────────────────────────────────────────────────────────────────────────

import type { ReadingQuestion } from './readingLibrary'

