/**
 * Строка уже по-русски. В сценах есть вопросы, заданные по-русски нарочно, —
 * о грамматике и о регистре («что это за форма?»); переводить в них нечего.
 */
function alreadyRu(s: string): boolean {
  return /[а-яё]/i.test(s)
}

/** Вопрос целиком написан по-русски — кнопке перевода нечего показывать. */
export function isAlreadyRu(q: ReadingQuestion): boolean {
  return alreadyRu(q.q) && q.options.every(alreadyRu)
}

/**
 * Перевод вопроса целиком — или ничего. Половинчатый перевод (формулировка на
 * русском, половина вариантов на языке оригинала) читается как сбой вёрстки и
 * мешает сильнее, чем отсутствие перевода: поэтому кнопки у такого вопроса нет.
 */
export function questionRu(lang: string, q: ReadingQuestion): { q: string; options: string[] } | undefined {
  if (isAlreadyRu(q)) return undefined
  const d = dict[lang]
  if (!d) return undefined
  // Русский вариант ответа внутри вопроса на изучаемом языке (так бывает у
  // вопросов о грамматике) переводить не нужно — он и есть свой перевод.
  const tr = (str: string) => d[str] ?? (alreadyRu(str) ? str : undefined)
  const head = tr(q.q)
  if (!head) return undefined
  const options: string[] = []
  for (const o of q.options) {
    const ru = tr(o)
    if (!ru) return undefined
    options.push(ru)
  }
  return { q: head, options }
}
